 e=byid(n); detail=n not in (854,860);u=e['sources'][-1]['url']; r={'original_id':f'zombia-soldier-detail-{n}','original_category':'Квесты: Стойкий солдатик','version':'ВКонтакте, историческая редакция','date':'16.07.2013 — дата публикации отдельной страницы' if detail else 'дата редакции не проверена','fields':{'Линейка':f'«Стойкий солдатик», позиция {n-845} из 16 по оглавлению ZOMBIA. Порядок разблокировки в игре не проверен.','Описание квеста':story,'Цели':goals,'Награда':reward,'Полнота':'Описания и цели опубликованы на фанатском сайте; другие игровые диалоги и актуальность версии не проверены.'},'confidence':'Отдельная страница прочитана.' if detail else 'Взято из ранее прочитанной карточки каталога; отдельная страница вернула только рекламный баннер.'}
